def backfill_catalogues():
    """Preserve article text/history; seed tenant-owned choices and primary links."""
    connection = op.get_bind()
    meta = sa.MetaData()
    household = sa.Table('household', meta, autoload_with=connection)
    items = sa.Table('household_item', meta, autoload_with=connection)
    category = sa.Table('category', meta, autoload_with=connection)
    source = sa.Table('purchase_source', meta, autoload_with=connection)
    links = sa.Table('item_source', meta, autoload_with=connection)
    for household_id in connection.scalars(sa.select(household.c.id)):
        rows = connection.execute(sa.select(items.c.id, items.c.category, items.c.source)
            .where(items.c.household_id == household_id)).all()
        source_ids = {}
        for table, defaults, column in (
            (category, ('Vorrat','Frisches','Getraenke','Haushalt','Pflege','Tierbedarf'), 'category'),
            (source, ('Laden','Coop','Migros','Galaxus'), 'source'),
        ):
            names = {}
            for value in list(defaults) + [getattr(row, column) for row in rows]:
                name = (value or ('Sonstiges' if column == 'category' else 'Laden')).strip()
                names.setdefault(normalize('NFKC', name).casefold(), name)
            for name_key, name in names.items():
                result = connection.execute(table.insert().values(household_id=household_id,
                    name=name, name_key=name_key, aliases=[], version=1))
                if column == 'source':
                    source_ids[name_key] = result.inserted_primary_key[0]
        for row in rows:
            name_key = normalize('NFKC', (row.source or 'Laden').strip()).casefold()
            connection.execute(links.insert().values(item_id=row.id, source_id=source_ids[name_key]))
